def make(n):
    # generate n different but syntactically valid regexes
    return [[f"^seg{i}.*val{i}$"] for i in range(n)]

def make(n):
    # generate n distinct simple regexes that all validate
    return [[f"pat{i}.*"] for i in range(n)]

def make(n):
    # generate n distinct harmless patterns
    return [[f"pattern_{i}"] for i in range(n)]
